'use client';

import React, { useState, useEffect, useRef } from 'react';
import {
    ArrowUpDown,
    Database,
    TrendingUp,
} from 'lucide-react';
import FadeinAnimation from '@/components/FadeinAnimation';
import Image from 'next/image';

const DEFAULT_LOGO= "data:image/png;base64,";

function HexCore({
  accent = "#e2ff3d",
  background = "#000000",
  hexSize = 34,
  sparkCount = 28,
  logoSrc = DEFAULT_LOGO,
  className = "",
}) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let width, height, cx, cy;
    let raf;

    const prefersReduced =
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    function hexToRgb(hex) {
      const h = hex.replace("#", "");
      const b = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
      return [(b >> 16) & 255, (b >> 8) & 255, b & 255];
    }
    const [ar, ag, ab] = hexToRgb(accent);
    const rgb = `${ar},${ag},${ab}`;

    let logoImg = null;
    let logoReady = false;
    if (logoSrc) {
      logoImg = new window.Image();
      logoImg.onload = () => {
        logoReady = true;
      };
      logoImg.src = logoSrc;
    }

    let gridCanvas;
    function buildGrid() {
      gridCanvas = document.createElement("canvas");
      gridCanvas.width = width * dpr;
      gridCanvas.height = height * dpr;
      const g = gridCanvas.getContext("2d");
      g.setTransform(dpr, 0, 0, dpr, 0, 0);
      g.strokeStyle = `rgba(${rgb},0.07)`;
      g.lineWidth = 1;

      const w = hexSize * 2;
      const hStep = hexSize * 1.5;
      const vStep = Math.sqrt(3) * hexSize;
      const cols = Math.ceil(width / hStep) + 2;
      const rows = Math.ceil(height / vStep) + 2;

      function hexPath(x, y) {
        g.beginPath();
        for (let i = 0; i < 6; i++) {
          const a = (Math.PI / 3) * i;
          const px = x + hexSize * Math.cos(a);
          const py = y + hexSize * Math.sin(a);
          if (i === 0) g.moveTo(px, py);
          else g.lineTo(px, py);
        }
        g.closePath();
        g.stroke();
      }

      for (let c = -1; c < cols; c++) {
        for (let r = -1; r < rows; r++) {
          const x = c * hStep;
          const y = r * vStep + (c % 2 !== 0 ? vStep / 2 : 0);
          hexPath(x, y);
        }
      }
    }

    function resize() {
      const rect = canvas.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      cx = width / 2;
      cy = height / 2;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      buildGrid();
    }

    function makeSpark() {
      const angle = Math.random() * Math.PI * 2;
      return {
        angle,
        wobble: (Math.random() - 0.5) * 0.6,
        speed: 0.9 + Math.random() * 1.6,
        dist: Math.random() * 30,
        maxDist: Math.hypot(width, height) * (0.7 + Math.random() * 0.5),
        trail: [],
      };
    }

    let sparks = [];
    let rings = []; 
    let started = false;

    function trySize() {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return false; 
      resize();
      sparks = Array.from({ length: sparkCount }).map(makeSpark);
      started = true;
      return true;
    }

    if (!trySize()) {
      let attempts = 0;
      const retry = setInterval(() => {
        attempts++;
        if (trySize() || attempts > 40) clearInterval(retry);
      }, 50);
    }

    const ro = new ResizeObserver(() => {
      resize();
      if (!started) {
        sparks = Array.from({ length: sparkCount }).map(makeSpark);
        started = true;
      }
    });
    ro.observe(canvas);

    let lastRing = 0;

    function frame(now) {
      if (!started) {
        raf = requestAnimationFrame(frame);
        return;
      }
      ctx.clearRect(0, 0, width, height);
      ctx.drawImage(gridCanvas, 0, 0, width, height);

      const coreR = 16;
      const breathe = prefersReduced ? 1 : 1 + Math.sin(now / 900) * 0.12;

      if (!prefersReduced && now - lastRing > 1800) {
        rings.push({ t0: now });
        lastRing = now;
      }
      rings = rings.filter((r) => now - r.t0 < 2200);
      rings.forEach((r) => {
        const p = (now - r.t0) / 2200;
        const radius = coreR + p * Math.min(width, height) * 0.42;
        ctx.beginPath();
        ctx.strokeStyle = `rgba(${rgb},${(0.35 * (1 - p)).toFixed(2)})`;
        ctx.lineWidth = 1.4;
        ctx.arc(cx, cy, radius, 0, Math.PI * 2);
        ctx.stroke();
      });

      sparks.forEach((s) => {
        if (!prefersReduced) {
          s.dist += s.speed;
          s.angle += s.wobble * 0.004;
          if (s.dist > s.maxDist) Object.assign(s, makeSpark());
        }
        const x = cx + Math.cos(s.angle) * s.dist;
        const y = cy + Math.sin(s.angle) * s.dist;
        s.trail.push({ x, y });
        if (s.trail.length > 7) s.trail.shift();

        const fade = 1 - s.dist / s.maxDist;
        s.trail.forEach((t, i) => {
          const a = ((i + 1) / s.trail.length) * 0.45 * fade;
          ctx.beginPath();
          ctx.fillStyle = `rgba(${rgb},${a.toFixed(2)})`;
          ctx.arc(t.x, t.y, 1.4, 0, Math.PI * 2);
          ctx.fill();
        });

        ctx.beginPath();
        const grad = ctx.createRadialGradient(x, y, 0, x, y, 7);
        grad.addColorStop(0, `rgba(${rgb},${(0.9 * fade).toFixed(2)})`);
        grad.addColorStop(1, `rgba(${rgb},0)`);
        ctx.fillStyle = grad;
        ctx.arc(x, y, 7, 0, Math.PI * 2);
        ctx.fill();
      });

      ctx.beginPath();
      const coreGlow = ctx.createRadialGradient(cx, cy, 0, cx, cy, coreR * 3.2 * breathe);
      coreGlow.addColorStop(0, `rgba(${rgb},0.55)`);
      coreGlow.addColorStop(1, `rgba(${rgb},0)`);
      ctx.fillStyle = coreGlow;
      ctx.arc(cx, cy, coreR * 3.2 * breathe, 0, Math.PI * 2);
      ctx.fill();

      if (logoSrc && logoReady) {
        const size = coreR * 2 * breathe;
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = "high";
        ctx.drawImage(logoImg, cx - size / 2, cy - size / 2, size, size);
      } else {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
          const a = (Math.PI / 3) * i;
          const r = coreR * breathe;
          const px = cx + r * Math.cos(a);
          const py = cy + r * Math.sin(a);
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.closePath();
        ctx.fillStyle = `rgba(${rgb},0.9)`;
        ctx.fill();
        ctx.strokeStyle = `rgba(${rgb},1)`;
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }

      raf = requestAnimationFrame(frame);
    }

    raf = requestAnimationFrame(frame);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
    };
  }, [accent, hexSize, sparkCount, logoSrc]);

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, background, overflow: "hidden" }}
    >
      <canvas ref={canvasRef} style={{ width: "100%", height: "100%", display: "block" }} />
    </div>
  );
}

export default function App() {
    const [fromAmount, setFromAmount] = useState('10,589.78');
    const [toAmount, setToAmount] = useState('9,842.15');
    const [fromCurrency, setFromCurrency] = useState('USD');
    const [toCurrency, setToCurrency] = useState('EUR');
    const [isConverting, setIsConverting] = useState(false);
    const [exchangeRate, setExchangeRate] = useState(0.93);

    const [creditBalance, setCreditBalance] = useState(8945.89);
    const handleRefreshBalance = () => {
        const randChange = (Math.random() * 400 - 200).toFixed(2);
        const newBalance = (parseFloat(creditBalance) + parseFloat(randChange)).toFixed(2);
        setCreditBalance(parseFloat(newBalance));
    };

    return (
        <div className="relative w-full bg-black font-sans overflow-x-hidden flex flex-col items-center">

            {/* ================= HEXCORE BACKGROUND ANIMATION ================= */}
            <HexCore accent="#e2ff3d" background="#000000" />

            <main className="relative z-10 max-w-7xl mx-auto w-full px-6 pt-32 pb-20 flex flex-col items-center text-center">

                {/* Hero Title */}
                <div className="relative mt-6 w-full max-w-4xl mx-auto flex flex-col items-center justify-center mb-6 text-center">
                    <span className="w-full font-rajdhani text-center text-5xl uppercase sm:text-6xl md:text-[160px] italic font-extrabold text-white tracking-tight leading-[1.1]">
                        Shabihaz
                    </span>
                    <FadeinAnimation />
                </div>

                {/* Subtitle Description */}
                <span className="max-w-xl font-rajdhani mx-auto text-center text-sm md:text-base text-white leading-relaxed mb-12 block">
                    Shabihaz Tech Solutions delivers expert Full Stack Development, secure Cloud Architecture, smart AI automation, and results-driven Digital Marketing services to scale your business growth.
                </span>

                {/* DYNAMIC INTERACTIVE VISUAL HERO WRAPPER */}
                <div className="relative w-full max-w-5xl mx-auto mt-4 flex flex-col lg:flex-row items-center justify-center gap-10 lg:gap-0">
                    <div className="absolute inset-0 max-w-3xl mx-auto rounded-full blur-3xl pointer-events-none -z-10" />
                </div>

            </main>
        </div>
    );
}
